-- EventosPeruIA: datos sintéticos de demostración. Contraseña: Prueba123.
-- Conserva los catálogos. Se detiene si existe información operativa.
-- Fechas relativas al momento de ejecución, en hora de Perú.
USE EventosPeruIA;
SET NOCOUNT ON;
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
SET ANSI_PADDING ON;
SET ANSI_WARNINGS ON;
SET ARITHABORT ON;
SET CONCAT_NULL_YIELDS_NULL ON;
SET NUMERIC_ROUNDABORT OFF;
SET XACT_ABORT ON;
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
BEGIN TRY
BEGIN TRANSACTION;
IF EXISTS (SELECT 1 FROM dbo.Usuario WITH (UPDLOCK,HOLDLOCK))
 OR EXISTS (SELECT 1 FROM dbo.Evento WITH (UPDLOCK,HOLDLOCK))
 OR EXISTS (SELECT 1 FROM dbo.Compra WITH (UPDLOCK,HOLDLOCK))
    THROW 51000, 'La base ya contiene datos operativos. No se modificó ningún registro.', 1;
DECLARE @Ahora datetime2 = CAST(SYSDATETIMEOFFSET() AT TIME ZONE 'SA Pacific Standard Time' AS datetime2);
DECLARE @Hoy datetime2 = CAST(CAST(@Ahora AS date) AS datetime2);
DECLARE @rolAsistente int=(SELECT IdRol FROM dbo.Rol WHERE Nombre='Asistente');
DECLARE @rolOrganizador int=(SELECT IdRol FROM dbo.Rol WHERE Nombre='Organizador');
DECLARE @rolAdministrador int=(SELECT IdRol FROM dbo.Rol WHERE Nombre='Administrador');
IF @rolAsistente IS NULL OR @rolOrganizador IS NULL OR @rolAdministrador IS NULL
    THROW 51001, 'Faltan los roles iniciales. No se modificó ningún registro.', 1;

DECLARE @cat1 int=(SELECT IdCategoria FROM dbo.Categoria WHERE Nombre=N'Concierto');
IF @cat1 IS NULL THROW 51002, 'Falta una categoría inicial.', 1;
DECLARE @cat2 int=(SELECT IdCategoria FROM dbo.Categoria WHERE Nombre=N'Taller');
IF @cat2 IS NULL THROW 51002, 'Falta una categoría inicial.', 1;
DECLARE @cat3 int=(SELECT IdCategoria FROM dbo.Categoria WHERE Nombre=N'Feria');
IF @cat3 IS NULL THROW 51002, 'Falta una categoría inicial.', 1;
DECLARE @cat4 int=(SELECT IdCategoria FROM dbo.Categoria WHERE Nombre=N'Charla');
IF @cat4 IS NULL THROW 51002, 'Falta una categoría inicial.', 1;
DECLARE @interes1 int=(SELECT IdInteres FROM dbo.Interes WHERE Nombre=N'Música' AND Estado=1);
IF @interes1 IS NULL THROW 51003, 'Falta un interés inicial activo.', 1;
DECLARE @interes2 int=(SELECT IdInteres FROM dbo.Interes WHERE Nombre=N'Tecnología' AND Estado=1);
IF @interes2 IS NULL THROW 51003, 'Falta un interés inicial activo.', 1;
DECLARE @interes3 int=(SELECT IdInteres FROM dbo.Interes WHERE Nombre=N'Gastronomía' AND Estado=1);
IF @interes3 IS NULL THROW 51003, 'Falta un interés inicial activo.', 1;
DECLARE @interes4 int=(SELECT IdInteres FROM dbo.Interes WHERE Nombre=N'Arte' AND Estado=1);
IF @interes4 IS NULL THROW 51003, 'Falta un interés inicial activo.', 1;
DECLARE @interes5 int=(SELECT IdInteres FROM dbo.Interes WHERE Nombre=N'Deporte' AND Estado=1);
IF @interes5 IS NULL THROW 51003, 'Falta un interés inicial activo.', 1;
DECLARE @interes6 int=(SELECT IdInteres FROM dbo.Interes WHERE Nombre=N'Negocios' AND Estado=1);
IF @interes6 IS NULL THROW 51003, 'Falta un interés inicial activo.', 1;
DECLARE @interes7 int=(SELECT IdInteres FROM dbo.Interes WHERE Nombre=N'Educación' AND Estado=1);
IF @interes7 IS NULL THROW 51003, 'Falta un interés inicial activo.', 1;
DECLARE @interes8 int=(SELECT IdInteres FROM dbo.Interes WHERE Nombre=N'Cultura' AND Estado=1);
IF @interes8 IS NULL THROW 51003, 'Falta un interés inicial activo.', 1;
