-- Comprobaciones antes de confirmar la transacción.
IF EXISTS (SELECT 1 FROM dbo.DetalleCompra d JOIN dbo.Compra c ON c.IdCompra=d.IdCompra
 WHERE (c.Estado<>'Rechazada' AND d.Cantidad<>(SELECT COUNT(*) FROM dbo.Entrada en WHERE en.IdDetalleCompra=d.IdDetalleCompra))
 OR (c.Estado='Rechazada' AND EXISTS(SELECT 1 FROM dbo.Entrada en WHERE en.IdDetalleCompra=d.IdDetalleCompra)))
 THROW 51004, 'La cantidad de entradas no coincide con la compra.', 1;
IF EXISTS (SELECT 1 FROM dbo.Evento ev WHERE ev.EntradasVendidas<>(
 SELECT COUNT(*) FROM dbo.Entrada en JOIN dbo.DetalleCompra d ON en.IdDetalleCompra=d.IdDetalleCompra
 WHERE d.IdEvento=ev.IdEvento AND en.Estado IN ('Valida','Utilizada')))
 THROW 51005, 'El aforo no coincide con las entradas.', 1;
IF EXISTS (SELECT 1 FROM dbo.Compra c WHERE c.MontoTotal<>(SELECT SUM(d.Subtotal) FROM dbo.DetalleCompra d WHERE d.IdCompra=c.IdCompra))
 THROW 51006, 'El monto de compra no coincide con los detalles.', 1;
COMMIT TRANSACTION;
PRINT 'Datos sintéticos cargados. Contraseña de las cuentas demo: Prueba123';
SELECT 'Usuarios' AS Tabla, COUNT(*) AS Filas FROM dbo.Usuario
UNION ALL SELECT 'Eventos',COUNT(*) FROM dbo.Evento
UNION ALL SELECT 'Compras',COUNT(*) FROM dbo.Compra
UNION ALL SELECT 'Entradas',COUNT(*) FROM dbo.Entrada;
SELECT IdUsuario,Correo,Estado FROM dbo.Usuario ORDER BY IdUsuario;
SELECT IdEvento,Nombre,Estado,FechaHoraInicio,AforoMaximo,EntradasVendidas FROM dbo.Evento ORDER BY IdEvento;
END TRY
BEGIN CATCH
 IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;
 THROW;
END CATCH;
